const rankingsBoxPlotStats = `-- name: RankingsBoxPlotStats :many
WITH representative_instances AS (
    SELECT DISTINCT ON (COALESCE(li.duplicate_group_id, li.id))
        li.id,
        COALESCE(li.duplicate_group_id, li.id) AS run_id
    FROM log_instances li
    ORDER BY COALESCE(li.duplicate_group_id, li.id),
        (li.id = li.duplicate_group_id) DESC NULLS LAST,
        li.start_time ASC,
        li.id ASC
),
deduped AS (
    SELECT DISTINCT ON (edr.player_guid, edr.encounter_name, ri.run_id)
        edr.player_guid,
        edr.encounter_name,
        edr.player_class,
        edr.player_spec,
        edr.realm_id,
        edr.damage_done,
        edr.healing_done,
        edr.absorbed_done,
        edr.duration_secs,
        ri.run_id
    FROM encounter_dps_rankings edr
    JOIN representative_instances ri ON ri.id = edr.instance_id
    JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
    WHERE CASE
        WHEN cardinality($2 :: text[]) > 0 THEN edr.instance_name = ANY($2 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($3 :: text[]) > 0 THEN edr.encounter_name = ANY($3 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($4 :: text[]) > 0 THEN edr.realm_name = ANY($4 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $5 :: text != '' THEN edr.player_role = $5
        ELSE true
    END
    AND CASE
        WHEN $6 :: bigint > 0 THEN edr.killed_at >= now() - make_interval(days => $6::int)
        ELSE true
    END
    AND CASE
        WHEN cardinality($7 :: text[]) > 0 THEN edr.difficulty_name = ANY($7 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $8 :: smallint > 0 THEN edr.max_players = $8
        ELSE true
    END
    ORDER BY edr.player_guid, edr.encounter_name, ri.run_id,
        (CASE WHEN $9 :: text = 'hps' THEN edr.hps ELSE edr.dps END) DESC
),
realm_encounter_counts AS (
    SELECT d.realm_id, COUNT(DISTINCT d.encounter_name) AS encounter_count
    FROM deduped d
    GROUP BY d.realm_id
),
per_run AS (
    SELECT
        d.player_class,
        d.player_spec,
        (CASE WHEN $9 :: text = 'hps'
            THEN SUM(d.healing_done + d.absorbed_done)::double precision / NULLIF(SUM(d.duration_secs), 0)
            ELSE SUM(d.damage_done)::double precision / NULLIF(SUM(d.duration_secs), 0)
        END)::double precision AS metric_value
    FROM deduped d
    JOIN realm_encounter_counts rec ON rec.realm_id = d.realm_id
    GROUP BY d.player_guid, d.run_id, d.player_class, d.player_spec, rec.encounter_count
    HAVING COUNT(DISTINCT d.encounter_name) = rec.encounter_count
)
SELECT
    s.player_class,
    s.player_spec,
    s.min_dps,
    s.q1_dps,
    s.median_dps,
    s.q3_dps,
    s.max_dps,
    s.count
FROM (
    SELECT
        d.player_class,
        (CASE WHEN $1 :: bool THEN '' ELSE d.player_spec END)::text AS player_spec,
        PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY d.metric_value) AS q1_dps,
        PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY d.metric_value) AS median_dps,
        PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY d.metric_value) AS q3_dps,
        -- When we have enough samples, trim the bottom 5% to exclude
        -- outliers (e.g. early deaths). Otherwise show the true minimum.
        CASE WHEN COUNT(*) > 100
            THEN PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY d.metric_value)
            ELSE MIN(d.metric_value)
        END::double precision AS min_dps,
        MAX(d.metric_value)::double precision AS max_dps,
        COUNT(*)::bigint AS count
    FROM per_run d
    WHERE d.metric_value > 0
    GROUP BY d.player_class, (CASE WHEN $1 :: bool THEN '' ELSE d.player_spec END)::text
) s
ORDER BY s.median_dps DESC
`

type RankingsBoxPlotStatsParams struct {
	GroupByClass     bool     `db:"group_by_class" json:"group_by_class"`
	InstanceNames    []string `db:"instance_names" json:"instance_names"`
	EncounterNames   []string `db:"encounter_names" json:"encounter_names"`
	RealmNames       []string `db:"realm_names" json:"realm_names"`
	Role             string   `db:"role" json:"role"`
	SinceDays        int64    `db:"since_days" json:"since_days"`
	DifficultyNames  []string `db:"difficulty_names" json:"difficulty_names"`
	FilterMaxPlayers int16    `db:"filter_max_players" json:"filter_max_players"`
	Metric           string   `db:"metric" json:"metric"`
}

type RankingsBoxPlotStatsRow struct {
	PlayerClass string  `db:"player_class" json:"player_class"`
	PlayerSpec  string  `db:"player_spec" json:"player_spec"`
	MinDps      float64 `db:"min_dps" json:"min_dps"`
	Q1Dps       float64 `db:"q1_dps" json:"q1_dps"`
	MedianDps   float64 `db:"median_dps" json:"median_dps"`
	Q3Dps       float64 `db:"q3_dps" json:"q3_dps"`
	MaxDps      float64 `db:"max_dps" json:"max_dps"`
	Count       int64   `db:"count" json:"count"`
}

// Returns box plot statistics (min, q1, median, q3, max, count) per class/spec.
// DPS is aggregated per run (sum damage / sum duration across encounters in one
// instance run), so each run is one data point. Matches leaderboard aggregation.
// Encounter counts are computed per realm: different realms (servers) can
// record different encounter names for the same instance, so requiring the
// union across realms would exclude every run when multiple realms are shown.
// Aggregate per player per run: sum damage/duration across encounters in one run.
// Each run becomes one data point for percentile computation.
// Only include runs where the player completed ALL encounters as the same spec.
func (q *sqlQuerier) RankingsBoxPlotStats(ctx context.Context, arg RankingsBoxPlotStatsParams) ([]RankingsBoxPlotStatsRow, error) {
	rows, err := q.db.Query(ctx, rankingsBoxPlotStats,
		arg.GroupByClass,
		arg.InstanceNames,
		arg.EncounterNames,
		arg.RealmNames,
		arg.Role,
		arg.SinceDays,
		arg.DifficultyNames,
		arg.FilterMaxPlayers,
		arg.Metric,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsBoxPlotStatsRow
	for rows.Next() {
		var i RankingsBoxPlotStatsRow
		if err := rows.Scan(
			&i.PlayerClass,
			&i.PlayerSpec,
			&i.MinDps,
			&i.Q1Dps,
			&i.MedianDps,
			&i.Q3Dps,
			&i.MaxDps,
			&i.Count,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

