const rankingsKillTimeStats = `-- name: RankingsKillTimeStats :many
WITH deduped AS (
    SELECT DISTINCT ON (lie.name, COALESCE(li.duplicate_group_id, li.id))
        lie.name AS encounter_name,
        EXTRACT(EPOCH FROM (lie.end_time - lie.start_time))::double precision AS duration_secs
    FROM log_instance_encounters lie
    JOIN log_instances li ON li.id = lie.instance_id
    JOIN wow_server_realms wsr ON wsr.id = li.realm_id
    WHERE li.name = $1
      AND lie.boss = true
      AND lie.kill_type = 'clean'
      AND CASE
          WHEN $2 :: bigint > 0 THEN lie.end_time >= now() - make_interval(days => $2::int)
          ELSE true
      END
    ORDER BY lie.name, COALESCE(li.duplicate_group_id, li.id), lie.end_time DESC
)
SELECT
    s.encounter_name,
    s.min_secs,
    s.q1_secs,
    s.median_secs,
    s.q3_secs,
    s.max_secs,
    s.count
FROM (
    SELECT
        d.encounter_name,
        PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY d.duration_secs) AS q1_secs,
        PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY d.duration_secs) AS median_secs,
        PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY d.duration_secs) AS q3_secs,
        MIN(d.duration_secs)::double precision AS min_secs,
        MAX(d.duration_secs)::double precision AS max_secs,
        COUNT(*)::bigint AS count
    FROM deduped d
    WHERE d.duration_secs > 0
    GROUP BY d.encounter_name
) s
ORDER BY (s.encounter_name = 'Trash'), s.encounter_name
`

type RankingsKillTimeStatsParams struct {
	InstanceName string `db:"instance_name" json:"instance_name"`
	SinceDays    int64  `db:"since_days" json:"since_days"`
}

type RankingsKillTimeStatsRow struct {
	EncounterName string  `db:"encounter_name" json:"encounter_name"`
	MinSecs       float64 `db:"min_secs" json:"min_secs"`
	Q1Secs        float64 `db:"q1_secs" json:"q1_secs"`
	MedianSecs    float64 `db:"median_secs" json:"median_secs"`
	Q3Secs        float64 `db:"q3_secs" json:"q3_secs"`
	MaxSecs       float64 `db:"max_secs" json:"max_secs"`
	Count         int64   `db:"count" json:"count"`
}

// Box plot stats on encounter duration (seconds) per encounter name.
// Deduplicates encounters across duplicate log groups.
func (q *sqlQuerier) RankingsKillTimeStats(ctx context.Context, arg RankingsKillTimeStatsParams) ([]RankingsKillTimeStatsRow, error) {
	rows, err := q.db.Query(ctx, rankingsKillTimeStats, arg.InstanceName, arg.SinceDays)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsKillTimeStatsRow
	for rows.Next() {
		var i RankingsKillTimeStatsRow
		if err := rows.Scan(
			&i.EncounterName,
			&i.MinSecs,
			&i.Q1Secs,
			&i.MedianSecs,
			&i.Q3Secs,
			&i.MaxSecs,
			&i.Count,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsLeaderboard = `-- name: RankingsLeaderboard :many
WITH representative_instances AS (
    SELECT DISTINCT ON (COALESCE(li.duplicate_group_id, li.id))
        li.id,
        COALESCE(li.duplicate_group_id, li.id) AS run_id
    FROM log_instances li
    ORDER BY COALESCE(li.duplicate_group_id, li.id),
        (li.id = li.duplicate_group_id) DESC NULLS LAST,
        li.start_time ASC,
        li.id ASC
),
deduped AS (
    SELECT DISTINCT ON (edr.player_guid, edr.encounter_name, ri.run_id)
        edr.player_guid,
        edr.player_name,
        edr.player_class,
        edr.player_spec,
        edr.player_role,
        edr.player_level,
        edr.instance_name,
        edr.encounter_name,
        edr.difficulty_name,
        edr.max_players,
        edr.realm_id,
        edr.realm_name,
        edr.guild_name,
        edr.damage_done,
        edr.healing_done,
        edr.absorbed_done,
        edr.duration_secs,
        edr.avg_ilvl,
        edr.log_hashed_slug,
        edr.killed_at,
        tb.sub_spec AS talent_sub_spec,
        tb.talent_layout AS talent_layout,
        ri.run_id
    FROM encounter_dps_rankings edr
    JOIN representative_instances ri ON ri.id = edr.instance_id
    JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
    LEFT JOIN talent_builds tb ON tb.id = edr.talent_build_id
    WHERE CASE
        WHEN cardinality($4 :: text[]) > 0 THEN edr.instance_name = ANY($4 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($5 :: text[]) > 0 THEN edr.encounter_name = ANY($5 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($6 :: text[]) > 0 THEN edr.realm_name = ANY($6 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $7 :: text != '' THEN edr.player_class = $7
        ELSE true
    END
    AND CASE
        WHEN $8 :: text != '' THEN edr.player_spec = $8
        ELSE true
    END
    AND CASE
        WHEN $9 :: text != '' THEN edr.player_role = $9
        ELSE true
    END
    AND CASE
        WHEN $10 :: bigint > 0 THEN edr.killed_at >= now() - make_interval(days => $10::int)
        ELSE true
    END
    AND CASE
        WHEN $11 :: bool THEN edr.player_class != 'Unknown' AND edr.player_spec != 'Unknown'
        ELSE true
    END
    AND CASE
        WHEN cardinality($12 :: text[]) > 0 THEN edr.difficulty_name = ANY($12 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $13 :: smallint > 0 THEN edr.max_players = $13
        ELSE true
    END
    AND (CASE WHEN $1 :: text = 'hps' THEN edr.hps ELSE edr.dps END) > 0
    ORDER BY edr.player_guid, edr.encounter_name, ri.run_id,
        (CASE WHEN $1 :: text = 'hps' THEN edr.hps ELSE edr.dps END) DESC
),
realm_encounter_counts AS (
    SELECT d.realm_id, COUNT(DISTINCT d.encounter_name) AS encounter_count
    FROM deduped d
    GROUP BY d.realm_id
),
per_run AS (
    SELECT
        d.player_guid,
        d.run_id,
        ((array_agg(d.player_name ORDER BY d.damage_done DESC))[1])::text AS player_name,
        ((array_agg(d.player_class ORDER BY d.damage_done DESC))[1])::text AS player_class,
        (string_agg(DISTINCT d.player_spec, '/' ORDER BY d.player_spec))::text AS player_spec,
        ((array_agg(d.player_role ORDER BY d.damage_done DESC))[1])::text AS player_role,
        MAX(d.player_level)::smallint AS player_level,
        ((array_agg(d.instance_name ORDER BY d.damage_done DESC))[1])::text AS instance_name,
        ((array_agg(d.encounter_name ORDER BY d.damage_done DESC))[1])::text AS encounter_name,
        ((array_agg(d.difficulty_name ORDER BY d.damage_done DESC))[1])::text AS difficulty_name,
        MAX(d.max_players)::smallint AS max_players,
        ((array_agg(d.realm_id ORDER BY d.damage_done DESC))[1])::uuid AS realm_id,
        ((array_agg(d.realm_name ORDER BY d.damage_done DESC))[1])::text AS realm_name,
        ((array_agg(d.guild_name ORDER BY d.damage_done DESC))[1])::text AS guild_name,
        SUM(d.damage_done)::bigint AS damage_done,
        SUM(d.healing_done)::bigint AS healing_done,
        SUM(d.absorbed_done)::bigint AS absorbed_done,
        SUM(d.duration_secs)::double precision AS duration_secs,
        (SUM(d.damage_done)::double precision / NULLIF(SUM(d.duration_secs), 0))::double precision AS dps,
        (SUM(d.healing_done + d.absorbed_done)::double precision / NULLIF(SUM(d.duration_secs), 0))::double precision AS hps,
        COALESCE(MAX(d.avg_ilvl), 0)::smallint AS avg_ilvl,
        ((array_agg(d.log_hashed_slug ORDER BY d.damage_done DESC))[1])::text AS log_hashed_slug,
        MAX(d.killed_at)::timestamptz AS killed_at,
        COALESCE((array_agg(d.talent_sub_spec ORDER BY d.damage_done DESC))[1], '')::text AS talent_sub_spec,
        COALESCE((array_agg(d.talent_layout ORDER BY d.damage_done DESC))[1], '')::text AS talent_layout
    FROM deduped d
    JOIN realm_encounter_counts rec ON rec.realm_id = d.realm_id
    GROUP BY d.player_guid, d.run_id, rec.encounter_count
    -- Only include runs where player has data for ALL encounters on their realm.
    HAVING COUNT(DISTINCT d.encounter_name) = rec.encounter_count
),
aggregated AS (
    SELECT DISTINCT ON (pr.player_guid)
        pr.player_guid,
        pr.player_name,
        pr.player_class,
        pr.player_spec,
        pr.player_role,
        pr.player_level,
        pr.instance_name,
        pr.encounter_name,
        pr.difficulty_name,
        pr.max_players,
        pr.realm_id,
        pr.realm_name,
        pr.guild_name,
        pr.damage_done,
        pr.healing_done,
        pr.absorbed_done,
        pr.duration_secs,
        pr.dps,
        pr.hps,
        pr.avg_ilvl,
        pr.log_hashed_slug,
        pr.killed_at,
        pr.talent_sub_spec,
        pr.talent_layout
    FROM per_run pr
    ORDER BY pr.player_guid, (CASE WHEN $1 :: text = 'hps' THEN pr.hps ELSE pr.dps END) DESC
)
SELECT
    a.player_guid, a.player_name, a.player_class, a.player_spec, a.player_role, a.player_level, a.instance_name, a.encounter_name, a.difficulty_name, a.max_players, a.realm_id, a.realm_name, a.guild_name, a.damage_done, a.healing_done, a.absorbed_done, a.duration_secs, a.dps, a.hps, a.avg_ilvl, a.log_hashed_slug, a.killed_at, a.talent_sub_spec, a.talent_layout,
    COUNT(*) OVER() AS total_count
FROM aggregated a
WHERE (CASE WHEN $1 :: text = 'hps' THEN a.hps ELSE a.dps END) > 0
ORDER BY (CASE WHEN $1 :: text = 'hps' THEN a.hps ELSE a.dps END) DESC
LIMIT $3::bigint
OFFSET $2::bigint
`

