// Returns paginated DPS rankings showing each player's best single run.
// A "run" is one instance_id (deduplicated by duplicate_group_id).
// Within a run, damage and duration are summed across encounters to get run DPS.
// Each player appears once with their highest-DPS run.
// Deduplicates by (player, encounter, duplicate_group) before aggregating.
// Encounter counts are computed per realm: different realms (servers) can
// record different encounter names for the same instance, so requiring the
// union across realms would exclude every run when multiple realms are shown.
// Step 1: aggregate per player per run (sum encounters within a single instance run).
// Step 2: pick each player's best run.
func (q *sqlQuerier) RankingsLeaderboard(ctx context.Context, arg RankingsLeaderboardParams) ([]RankingsLeaderboardRow, error) {
	rows, err := q.db.Query(ctx, rankingsLeaderboard,
		arg.Metric,
		arg.QueryOffset,
		arg.QueryLimit,
		arg.InstanceNames,
		arg.EncounterNames,
		arg.RealmNames,
		arg.Class,
		arg.Spec,
		arg.Role,
		arg.SinceDays,
		arg.HideUnknowns,
		arg.DifficultyNames,
		arg.FilterMaxPlayers,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsLeaderboardRow
	for rows.Next() {
		var i RankingsLeaderboardRow
		if err := rows.Scan(
			&i.PlayerGuid,
			&i.PlayerName,
			&i.PlayerClass,
			&i.PlayerSpec,
			&i.PlayerRole,
			&i.PlayerLevel,
			&i.InstanceName,
			&i.EncounterName,
			&i.DifficultyName,
			&i.MaxPlayers,
			&i.RealmID,
			&i.RealmName,
			&i.GuildName,
			&i.DamageDone,
			&i.HealingDone,
			&i.AbsorbedDone,
			&i.DurationSecs,
			&i.Dps,
			&i.Hps,
			&i.AvgIlvl,
			&i.LogHashedSlug,
			&i.KilledAt,
			&i.TalentSubSpec,
			&i.TalentLayout,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

