const siteStats = `-- name: SiteStats :one
SELECT
    (SELECT COUNT(*)
       FROM log_instances li
       JOIN wow_server_realms wsr ON wsr.id = li.realm_id)::bigint AS logs_parsed,
    (SELECT COUNT(*)
       FROM game_players gp
       JOIN wow_server_realms wsr ON wsr.id = gp.realm_id)::bigint AS players_tracked,
    (SELECT COUNT(*)
       FROM guilds g
       JOIN wow_server_realms wsr ON wsr.id = g.realm_id)::bigint AS guild_count,
    (SELECT COUNT(*)
       FROM log_instance_encounters lie
       JOIN log_instances li ON li.id = lie.instance_id
       JOIN wow_server_realms wsr ON wsr.id = li.realm_id
      WHERE lie.boss = true
        AND lie.kill_type IN ('clean', 'partial'))::bigint AS boss_kills
`

type SiteStatsRow struct {
	LogsParsed     int64 `db:"logs_parsed" json:"logs_parsed"`
	PlayersTracked int64 `db:"players_tracked" json:"players_tracked"`
	GuildCount     int64 `db:"guild_count" json:"guild_count"`
	BossKills      int64 `db:"boss_kills" json:"boss_kills"`
}

// Aggregate public site statistics for the homepage.
// Each subquery JOINs wow_server_realms so RLS tenant filtering cascades.
func (q *sqlQuerier) SiteStats(ctx context.Context) (SiteStatsRow, error) {
	row := q.db.QueryRow(ctx, siteStats)
	var i SiteStatsRow
	err := row.Scan(
		&i.LogsParsed,
		&i.PlayersTracked,
		&i.GuildCount,
		&i.BossKills,
	)
	return i, err
}

const getInstanceCleanEncounterKillTimes = `-- name: GetInstanceCleanEncounterKillTimes :many
SELECT
    lie.name AS encounter_name,
    (EXTRACT(EPOCH FROM (lie.end_time - lie.start_time)) * 1000)::bigint AS duration_ms
FROM log_instance_encounters lie
WHERE lie.instance_id = $1
  AND lie.boss = true
  AND lie.kill_type = 'clean'
  AND lie.end_time > lie.start_time
ORDER BY lie.start_time
`

type GetInstanceCleanEncounterKillTimesRow struct {
	EncounterName string `db:"encounter_name" json:"encounter_name"`
	DurationMs    int64  `db:"duration_ms" json:"duration_ms"`
}

// Returns only clean boss kills for an instance, excluding partial kills.
// Used by the time-parse handler so the primary instance is scored against
// the clean-only snapshot cohort consistently.
func (q *sqlQuerier) GetInstanceCleanEncounterKillTimes(ctx context.Context, instanceID uuid.UUID) ([]GetInstanceCleanEncounterKillTimesRow, error) {
	rows, err := q.db.Query(ctx, getInstanceCleanEncounterKillTimes, instanceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetInstanceCleanEncounterKillTimesRow
	for rows.Next() {
		var i GetInstanceCleanEncounterKillTimesRow
		if err := rows.Scan(&i.EncounterName, &i.DurationMs); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

